  const w2y = Math.cos(sy*0.028-t*0.38)*6 + Math.sin(sx*0.022+t*0.42)*5;
  const px = sx+w2x, py = sy+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0.7],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.8],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,0.6],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.9],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,0.5],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.75],
    [60+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+1)*50,0.14,1.3,0.85],
    [420+Math.cos(t*0.55+2)*60,200+Math.sin(t*0.75+4)*40,0.11,2.1,0.65],
    [300+Math.sin(t*0.25)*110,30+Math.cos(t*0.45+2)*60,0.055,2.8,0.55],
    [100+Math.cos(t*0.7+3)*90,220+Math.sin(t*0.5+5)*50,0.13,1.6,0.7]
  ];
  let aS=0,iS=0,tw=0;
  for(const[sX,sY,f,sp,w]of src){const d=Math.sqrt((px-sX)**2+(py-sY)**2);aS+=Math.sin(d*f-t*sp)*w;iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;tw+=w;}
  aS/=tw;iS/=tw;
  const bg1=(Math.sin(px*0.04+py*0.025+t*0.8)+Math.sin(px*0.03-py*0.04+t*1.1))/2;
  const bg2=Math.sin((px+py)*0.12+t*2.5)*0.2+Math.sin((px-py)*0.1-t*2)*0.2;
  const bg3=Math.sin(px*0.08+t*0.5)*Math.sin(py*0.09-t*0.6)*0.3;
  const bg=bg1+bg2+bg3;
  const dist=Math.sqrt((px-cx)**2+(py-cy)**2),ang=Math.atan2(py-cy,px-cx);
