  const r1=Math.tanh((aS-iS*0.7+bg*0.3+spiral)*2.2);
  const aS2=Math.sin(px*0.06-py*0.04+t*0.9)+Math.sin(dist*0.03+ang*2-t*0.7)*0.5;
  const iS2=Math.cos(px*0.05+py*0.05-t*0.6)+Math.sin(dist*0.04-ang*3+t*0.5)*0.5;
  const r2=Math.tanh((aS2-iS2*0.5)*1.8);
  const coupled=Math.tanh(r1*0.6+r2*0.4+r1*r2*0.3);
  const cell=Math.tanh((Math.sin(px*0.15)*Math.sin(py*0.15)+Math.sin((px+py)*0.1+t)*0.5)*1.5)*0.3;
  const fine=Math.sin(px*0.3+t*3)*Math.sin(py*0.35-t*2.5)*0.12;
  const blend=coupled*0.6+cell*0.2+fine*0.1+spiral*0.1;
  const v=blend*0.5+0.5;
  const pal=[[5,12,52],[12,45,85],[18,95,105],[25,155,130],[180,195,60],[225,160,50],[210,95,55],[165,50,65],[95,25,55],[40,15,48],[5,12,52]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const sf=f*f*(3-2*f);
  const lum=0.82+Math.sin(coupled*Math.PI)*0.18;
  const edge=Math.abs(coupled)>0.65?1.12:Math.abs(coupled)>0.3?1.04:0.94;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum*edge)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum*edge)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum*edge)|0
  ];
}
